// 1. \u5b9a\u4e49\u53d1\u5e03\u8005, \u53d1\u5e03\u7684\u6570\u636e\u7c7b\u578b\u662f Integer\n        // \u76f4\u63a5\u4f7f\u7528jdk\u81ea\u5e26\u7684SubmissionPublisher, \u5b83\u5b9e\u73b0\u4e86 Publisher \u63a5\u53e3\n        SubmissionPublisher<Integer> publiser = new SubmissionPublisher<>();\n\n        // 2. \u5b9a\u4e49\u8ba2\u9605\u8005\n        Flow.Subscriber<Integer> subscriber = new Flow.Subscriber<>() {\n\n            private Flow.Subscription subscription;\n\n            @Override\n            public void onSubscribe(Flow.Subscription subscription) {\n                // \u4fdd\u5b58\u8ba2\u9605\u5173\u7cfb, \u9700\u8981\u7528\u5b83\u6765\u7ed9\u53d1\u5e03\u8005\u54cd\u5e94\n                this.subscription = subscription;\n\n                // \u8bf7\u6c42\u4e00\u4e2a\u6570\u636e\n                this.subscription.request(1);\n            }\n\n            @Override\n            public void onNext(Integer item) {\n                // \u63a5\u53d7\u5230\u4e00\u4e2a\u6570\u636e, \u5904\u7406\n                System.out.println("\u63a5\u53d7\u5230\u6570\u636e: " + item);\n\n                // \u5904\u7406\u5b8c\u8c03\u7528request\u518d\u8bf7\u6c42\u4e00\u4e2a\u6570\u636e\n                this.subscription.request(1);\n\n                // \u6216\u8005\u5df2\u7ecf\u8fbe\u5230\u4e86\u76ee\u6807, \u53ef\u4ee5\u8c03\u7528cancel\u544a\u8bc9\u53d1\u5e03\u8005\u4e0d\u518d\u63a5\u53d7\u6570\u636e\u4e86\n                // this.subscription.cancel();\n            }\n\n            @Override\n            public void onError(Throwable throwable) {\n                // \u51fa\u73b0\u4e86\u5f02\u5e38(\u4f8b\u5982\u5904\u7406\u6570\u636e\u7684\u65f6\u5019\u4ea7\u751f\u4e86\u5f02\u5e38)\n                throwable.printStackTrace();\n\n                // \u6211\u4eec\u53ef\u4ee5\u544a\u8bc9\u53d1\u5e03\u8005, \u540e\u9762\u4e0d\u63a5\u53d7\u6570\u636e\u4e86\n                this.subscription.cancel();\n            }\n\n            @Override\n            public void onComplete() {\n                // \u5168\u90e8\u6570\u636e\u5904\u7406\u5b8c\u4e86(\u53d1\u5e03\u8005\u5173\u95ed\u4e86)\n                System.out.println("\u5904\u7406\u5b8c\u4e86!");\n            }\n\n        };\n\n        // 3. \u53d1\u5e03\u8005\u548c\u8ba2\u9605\u8005 \u5efa\u7acb\u8ba2\u9605\u5173\u7cfb\n        publiser.subscribe(subscriber);\n\n        // 4. \u751f\u4ea7\u6570\u636e, \u5e76\u53d1\u5e03\n        // \u8fd9\u91cc\u5ffd\u7565\u6570\u636e\u751f\u4ea7\u8fc7\u7a0b\n        for (int i = 0; i < 3; i++) {\n            System.out.println("\u751f\u6210\u6570\u636e:" + i);\n            // submit\u662f\u4e2ablock\u65b9\u6cd5\n            publiser.submit(i);\n        }\n\n        // 5. \u7ed3\u675f\u540e \u5173\u95ed\u53d1\u5e03\u8005\n        // \u6b63\u5f0f\u73af\u5883 \u5e94\u8be5\u653e finally \u6216\u8005\u4f7f\u7528 try-resouce \u786e\u4fdd\u5173\u95ed\n        publiser.close();\n\n        // \u4e3b\u7ebf\u7a0b\u5ef6\u8fdf\u505c\u6b62, \u5426\u5219\u6570\u636e\u6ca1\u6709\u6d88\u8d39\u5c31\u4f1a\u9000\u51fa\n        Thread.currentThread().join(1000);\n        // debug\u7684\u65f6\u5019, \u4e0b\u9762\u8fd9\u884c\u9700\u8981\u6709\u65ad\u70b9\n        // \u5426\u5219\u4e3b\u7ebf\u7a0b\u7ed3\u675f\u65e0\u6cd5debug\n        System.out.println();\n    }\n}\n'})}),"\n",(0,s.jsx)(n.p,{children:"\u8fd0\u884c\u7ed3\u679c\u5982\u4e0b\uff1a"}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{src:"https://image.quicktoolset.top/images/2021/08/29/20210829135745.png",alt:""})}),"\n",(0,s.jsx)(n.p,{children:"\u4e0a\u6587\u4e2d\u63d0\u5230\u8fc7\u53ef\u4ee5\u8c03\u8282\u53d1\u5e03\u8005\u7684\u6570\u636e\u4ea7\u51fa\u901f\u5ea6\uff0c\u90a3\u4e48\u8fd9\u4e2a\u901f\u5ea6\u662f\u5982\u4f55\u8c03\u8282\u7684\u5462\uff1f\u5173\u952e\u5c31\u5728\u4e8e submit \u65b9\u6cd5\uff0c\u8be5\u65b9\u6cd5\u662f\u4e00\u4e2a\u963b\u585e\u65b9\u6cd5\u3002\u9700\u8981\u5148\u8bf4\u660e\u7684\u662f SubmissionPublisher \u91cc\u6709\u4e00\u4e2a\u6570\u636e\u7f13\u51b2\u533a\uff0c\u7528\u4e8e\u7f13\u51b2\u53d1\u5e03\u8005\u4ea7\u751f\u7684\u6570\u636e\uff0c\u800c\u8fd9\u4e2a\u7f13\u51b2\u533a\u662f\u5229\u7528\u4e00\u4e2a Object \u6570\u7ec4\u5b9e\u73b0\u7684\uff0c\u7f13\u51b2\u533a\u6700\u5927\u957f\u5ea6\u4e3a 256\u3002\u6211\u4eec\u53ef\u4ee5\u5728 onSubscribe \u65b9\u6cd5\u91cc\u6253\u4e0a\u65ad\u70b9\uff0c\u67e5\u770b\u5230\u8fd9\u4e2a\u7f13\u51b2\u533a\uff1a"}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{src:"https://image.quicktoolset.top/images/2021/08/29/20210829135814.png",alt:""})}),"\n",(0,s.jsx)(n.p,{children:"\u5f53\u8fd9\u4e2a\u7f13\u51b2\u533a\u7684\u6570\u636e\u6ee1\u4e86\u4e4b\u540e\uff0csubmit \u65b9\u6cd5\u5c31\u4f1a\u8fdb\u5165\u963b\u585e\u72b6\u6001\uff0c\u53d1\u5e03\u8005\u6570\u636e\u7684\u4ea7\u751f\u901f\u5ea6\u5c31\u4f1a\u53d8\u6162\uff0c\u4ee5\u6b64\u5b9e\u73b0\u8c03\u8282\u53d1\u5e03\u8005\u7684\u6570\u636e\u4ea7\u51fa\u901f\u5ea6\u3002"}),"\n",(0,s.jsx)(n.h2,{id:"\u7ed3\u5408-processor-\u7684\u4f7f\u7528\u65b9\u5f0f",children:"\u7ed3\u5408 Processor \u7684\u4f7f\u7528\u65b9\u5f0f"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-java",children:'/**\n * Processor, \u9700\u8981\u7ee7\u627fSubmissionPublisher\u5e76\u5b9e\u73b0Processor\u63a5\u53e3\n *\n * \u8f93\u5165\u6e90\u6570\u636e integer, \u8fc7\u6ee4\u6389\u5c0f\u4e8e0\u7684, \u7136\u540e\u8f6c\u6362\u6210\u5b57\u7b26\u4e32\u53d1\u5e03\u51fa\u53bb\n */\nclass MyProcessor extends SubmissionPublisher<String>\n        implements Processor<Integer, String> {\n\n    private Subscription subscription;\n\n    @Override\n    public void onSubscribe(Subscription subscription) {\n        // \u4fdd\u5b58\u8ba2\u9605\u5173\u7cfb, \u9700\u8981\u7528\u5b83\u6765\u7ed9\u53d1\u5e03\u8005\u54cd\u5e94\n        this.subscription = subscription;\n\n        // \u8bf7\u6c42\u4e00\u4e2a\u6570\u636e\n        this.subscription.request(1);\n    }\n\n    @Override\n    public void onNext(Integer item) {\n        // \u63a5\u53d7\u5230\u4e00\u4e2a\u6570\u636e, \u5904\u7406\n        System.out.println("\u5904\u7406\u5668\u63a5\u53d7\u5230\u6570\u636e: " + item);\n\n        // \u8fc7\u6ee4\u6389\u5c0f\u4e8e0\u7684, \u7136\u540e\u53d1\u5e03\u51fa\u53bb\n        if (item > 0) {\n            this.submit("\u8f6c\u6362\u540e\u7684\u6570\u636e:" + item);\n        }\n\n        // \u5904\u7406\u5b8c\u8c03\u7528request\u518d\u8bf7\u6c42\u4e00\u4e2a\u6570\u636e\n        this.subscription.request(1);\n\n        // \u6216\u8005 \u5df2\u7ecf\u8fbe\u5230\u4e86\u76ee\u6807, \u8c03\u7528cancel\u544a\u8bc9\u53d1\u5e03\u8005\u4e0d\u518d\u63a5\u53d7\u6570\u636e\u4e86\n        // this.subscription.cancel();\n    }\n\n    @Override\n    public void onError(Throwable throwable) {\n        // \u51fa\u73b0\u4e86\u5f02\u5e38(\u4f8b\u5982\u5904\u7406\u6570\u636e\u7684\u65f6\u5019\u4ea7\u751f\u4e86\u5f02\u5e38)\n        throwable.printStackTrace();\n\n        // \u6211\u4eec\u53ef\u4ee5\u544a\u8bc9\u53d1\u5e03\u8005, \u540e\u9762\u4e0d\u63a5\u53d7\u6570\u636e\u4e86\n        this.subscription.cancel();\n    }\n\n    @Override\n    public void onComplete() {\n        // \u5168\u90e8\u6570\u636e\u5904\u7406\u5b8c\u4e86(\u53d1\u5e03\u8005\u5173\u95ed\u4e86)\n        System.out.println("\u5904\u7406\u5668\u5904\u7406\u5b8c\u4e86!");\n        // \u5173\u95ed\u53d1\u5e03\u8005\n        this.close();\n    }\n\n}\n\n/**\n * \u5e26 process \u7684 flow demo\n * @author 01\n */\npublic class FlowDemo2 {\n\n    public static void main(String[] args) throws Exception {\n        // 1. \u5b9a\u4e49\u53d1\u5e03\u8005, \u53d1\u5e03\u7684\u6570\u636e\u7c7b\u578b\u662f Integer\n        // \u76f4\u63a5\u4f7f\u7528jdk\u81ea\u5e26\u7684SubmissionPublisher\n        SubmissionPublisher<Integer> publiser = new SubmissionPublisher<>();\n\n        // 2. \u5b9a\u4e49\u5904\u7406\u5668, \u5bf9\u6570\u636e\u8fdb\u884c\u8fc7\u6ee4, \u5e76\u8f6c\u6362\u4e3aString\u7c7b\u578b\n        MyProcessor processor = new MyProcessor();\n\n        // 3. \u53d1\u5e03\u8005 \u548c \u5904\u7406\u5668 \u5efa\u7acb\u8ba2\u9605\u5173\u7cfb\n        publiser.subscribe(processor);\n\n        // 4. \u5b9a\u4e49\u6700\u7ec8\u8ba2\u9605\u8005, \u6d88\u8d39 String \u7c7b\u578b\u6570\u636e\n        Subscriber<String> subscriber = new Subscriber<>() {\n\n            private Subscription subscription;\n\n            @Override\n            public void onSubscribe(Subscription subscription) {\n                // \u4fdd\u5b58\u8ba2\u9605\u5173\u7cfb, \u9700\u8981\u7528\u5b83\u6765\u7ed9\u53d1\u5e03\u8005\u54cd\u5e94\n                this.subscription = subscription;\n\n                // \u8bf7\u6c42\u4e00\u4e2a\u6570\u636e\n                this.subscription.request(1);\n            }\n\n            @Override\n            public void onNext(String item) {\n                // \u63a5\u53d7\u5230\u4e00\u4e2a\u6570\u636e, \u5904\u7406\n                System.out.println("\u63a5\u53d7\u5230\u6570\u636e: " + item);\n\n                // \u5904\u7406\u5b8c\u8c03\u7528request\u518d\u8bf7\u6c42\u4e00\u4e2a\u6570\u636e\n                this.subscription.request(1);\n\n                // \u6216\u8005 \u5df2\u7ecf\u8fbe\u5230\u4e86\u76ee\u6807, \u8c03\u7528cancel\u544a\u8bc9\u53d1\u5e03\u8005\u4e0d\u518d\u63a5\u53d7\u6570\u636e\u4e86\n                // this.subscription.cancel();\n            }\n\n            @Override\n            public void onError(Throwable throwable) {\n                // \u51fa\u73b0\u4e86\u5f02\u5e38(\u4f8b\u5982\u5904\u7406\u6570\u636e\u7684\u65f6\u5019\u4ea7\u751f\u4e86\u5f02\u5e38)\n                throwable.printStackTrace();\n\n                // \u6211\u4eec\u53ef\u4ee5\u544a\u8bc9\u53d1\u5e03\u8005, \u540e\u9762\u4e0d\u63a5\u53d7\u6570\u636e\u4e86\n                this.subscription.cancel();\n            }\n\n            @Override\n            public void onComplete() {\n                // \u5168\u90e8\u6570\u636e\u5904\u7406\u5b8c\u4e86(\u53d1\u5e03\u8005\u5173\u95ed\u4e86)\n                System.out.println("\u5904\u7406\u5b8c\u4e86!");\n            }\n\n        };\n\n        // 5. \u5904\u7406\u5668 \u548c \u6700\u7ec8\u8ba2\u9605\u8005 \u5efa\u7acb\u8ba2\u9605\u5173\u7cfb\n        processor.subscribe(subscriber);\n\n        // 6. \u751f\u4ea7\u6570\u636e, \u5e76\u53d1\u5e03\n        // \u8fd9\u91cc\u5ffd\u7565\u6570\u636e\u751f\u4ea7\u8fc7\u7a0b\n        publiser.submit(-111);\n        publiser.submit(111);\n\n        // 7. \u7ed3\u675f\u540e \u5173\u95ed\u53d1\u5e03\u8005\n        // \u6b63\u5f0f\u73af\u5883 \u5e94\u8be5\u653e finally \u6216\u8005\u4f7f\u7528 try-resouce \u786e\u4fdd\u5173\u95ed\n        publiser.close();\n\n        // \u4e3b\u7ebf\u7a0b\u5ef6\u8fdf\u505c\u6b62, \u5426\u5219\u6570\u636e\u6ca1\u6709\u6d88\u8d39\u5c31\u9000\u51fa\n        Thread.currentThread().join(1000);\n    }\n}\n'})}),"\n",(0,s.jsx)(n.p,{children:"\u8fd0\u884c\u7ed3\u679c\u5982\u4e0b\uff1a"}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{src:"https://image.quicktoolset.top/images/2021/08/29/20210829135935.png",alt:""})})]})}function b(e={}){const{wrapper:n}={...(0,t.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},7168:(e,n,i)=>{i.d(n,{R:()=>c,x:()=>l});var r=i(30758);const s={},t=r.createContext(s);function c(e){const n=r.useContext(t);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:c(e.components),r.createElement(t.Provider,{value:n},e.children)}}}]);